import React from 'react';
import { FaServer, FaChartLine, FaUniversity, FaUsers, FaProjectDiagram } from 'react-icons/fa';
import "./whyme.css";

const Whyme = () => {
  // ... keep the existing expertiseAreas array ...
  const expertiseAreas = [
    {
      icon: <FaServer />,
      title: "Enterprise-Grade Distributed Systems",
      points: [
        "30% reduction in system downtime through fault-tolerant microservices",
        "40% faster deployment cycles with Kubernetes/Terraform orchestration",
        "20,000+ daily transactions processed with 99.9% uptime"
      ]
    },
    {
      icon: <FaChartLine />,
      title: "Full-Stack Observability",
      points: [
        "55% faster incident resolution with OpenTelemetry tracing",
        "15+ critical bottlenecks identified via Prometheus/Grafana",
        "38% improved node sync in blockchain networks"
      ]
    },
    {
      icon: <FaUniversity />,
      title: "Academic Rigor & Implementation",
      points: [
        "MSc AI research applied to distributed systems (92% accuracy under load)",
        "25% network throughput boost via kernel-level TCP/IP optimizations",
        "IEEE-published blockchain consensus innovations"
      ]
    },
    {
      icon: <FaUsers />,
      title: "Engineering Leadership",
      points: [
        "300+ developers trained on GCP best practices",
        "60% reduction in incident impact through RCA playbooks",
        "5x traffic spike handling in hackathon architectures"
      ]
    },
    {
      icon: <FaProjectDiagram />,
      title: "Systematic Approach",
      points: [
        "95% test coverage requirements analysis",
        "70% risk reduction via iterative prototyping",
        "40% velocity boost through metrics-driven planning"
      ]
    }
  ];
  return (
    <div className="why-me-container">
      <div className="section-container">
        {/* Image Section */}
      

        {/* Content Section */}
        <div className="content-section">
          <h1 className="section-title">Why Choose Me?</h1>
          <div className="expertise-grid">
            {expertiseAreas.map((area, index) => (
              <div className="expertise-card" key={index}>
                <div className="card-header">
                  <div className="card-icon">{area.icon}</div>
                  <h2 className="card-title">{area.title}</h2>
                </div>
                <ul className="card-points">
                  {area.points.map((point, idx) => (
                    <li key={idx} className="card-point">
                      <div className="point-marker"></div>
                      {point}
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Whyme;
