import React from 'react';
import Carousel from 'react-bootstrap/Carousel';
import './Certification.css';

// Dynamically import all images from the 'images' folder
const importAllImages = (requireContext) => {
  return requireContext.keys().map(requireContext);
};

// Import images (adjust path based on your project structure)
const images = importAllImages(require.context('../certificates', false, /\.(png|jpe?g|gif)$/));

const Certification = () => {
  return (
    <div>
      <h1 className="HeadingCert">Certifications</h1>
      <Carousel>
        {images.map((image, index) => (
          <Carousel.Item key={index}>
            <img
              className="carousel-image"
              src={image}
              alt={`Slide ${index + 1}`}
            />
            <Carousel.Caption>
              <h3>Slide {index + 1}</h3>
              <p>Description for slide {index + 1}</p>
            </Carousel.Caption>
          </Carousel.Item>
        ))}
      </Carousel>
    </div>
  );
};

export default Certification;
