import React from 'react';
import { SocialIcon } from 'react-social-icons';
import './Footer.css';

const Footer = () => {
  return (
    <footer className="footer">
      <div className="social-container">
        <SocialIcon url="https://twitter.com/yourhandle" network="twitter" style={{ height: 35, width: 35, margin: '0 10px' }} />
        <SocialIcon url="https://linkedin.com/in/yourprofile" network="linkedin" style={{ height: 35, width: 35, margin: '0 10px' }} />
        <SocialIcon url="https://github.com/yourusername" network="github" style={{ height: 35, width: 35, margin: '0 10px' }} />
        <SocialIcon url="https://instagram.com/yourprofile" network="instagram" style={{ height: 35, width: 35, margin: '0 10px' }} />
      </div>
      
    </footer>
  );
};

export default Footer;
